-- Isolated finance tables. All writes retain caller RLS; no service-role client is needed.
create table public.fd_businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,representative text not null default '',kind text not null default '개인' check(kind in ('개인','법인')),reserve bigint not null default 0 check(reserve>=0 and reserve<=9007199254740991),color text not null default '#3366ee',created_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,name));
create table public.fd_accounts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,business_id uuid not null,name text not null,bank text not null default '',masked_number text not null default '' check(masked_number ~ '^[0-9]{0,3}$'),opening_balance bigint not null default 0 check(abs(opening_balance::numeric)<=9007199254740991),opening_balance_date date,created_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,business_id,id),unique(owner_id,business_id,name),foreign key(owner_id,business_id) references public.fd_businesses(owner_id,id) on delete cascade);
create table public.fd_categories(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,group_name text not null,is_operating boolean not null default false,is_internal boolean not null default false,created_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,name));
create table public.fd_category_rules(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,pattern text not null,field text not null check(field in ('description','raw_gwamok')),category_id uuid not null,priority integer not null default 40,is_internal boolean not null default false,created_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,pattern,field),foreign key(owner_id,category_id) references public.fd_categories(owner_id,id));
create table public.fd_gwamok_aliases(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,raw_name text not null,standard_name text not null,created_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,raw_name));
create table public.fd_uploads(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null,filename text not null,storage_path text not null,success_count integer not null default 0,duplicate_count integer not null default 0,error_count integer not null default 0,errors jsonb not null default '[]',created_at timestamptz not null default now(),unique(owner_id,id),foreign key(owner_id,account_id) references public.fd_accounts(owner_id,id));
create table public.fd_transactions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,business_id uuid not null,account_id uuid not null,upload_id uuid,txn_date date not null,amount bigint not null check(amount>0 and amount<=9007199254740991),direction text not null check(direction in ('in','out')),description text not null default '',raw_gwamok text not null default '',category_id uuid,is_internal boolean not null default false,balance bigint check(balance is null or abs(balance::numeric)<=9007199254740991),tax_invoice boolean not null default false,dedup_hash text not null,manually_classified boolean not null default false,created_at timestamptz not null default now(),unique(owner_id,id),unique(account_id,dedup_hash),foreign key(owner_id,business_id,account_id) references public.fd_accounts(owner_id,business_id,id),foreign key(owner_id,category_id) references public.fd_categories(owner_id,id),foreign key(owner_id,upload_id) references public.fd_uploads(owner_id,id) on delete cascade);
create table public.fd_recurring_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,business_id uuid not null,title text not null,amount bigint not null check(amount>0 and amount<=9007199254740991),direction text not null check(direction in ('in','out')),day integer not null check(day between 1 and 31),frequency text not null default 'monthly' check(frequency in ('monthly','once')),start_date date not null,end_date date,created_at timestamptz not null default now(),unique(owner_id,id),foreign key(owner_id,business_id) references public.fd_businesses(owner_id,id) on delete cascade,check(end_date is null or end_date>=start_date));
create table public.fd_inter_company_links(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,out_transaction_id uuid not null,in_transaction_id uuid not null,created_at timestamptz not null default now(),unique(owner_id,id),unique(out_transaction_id),unique(in_transaction_id),check(out_transaction_id<>in_transaction_id),foreign key(owner_id,out_transaction_id) references public.fd_transactions(owner_id,id) on delete cascade,foreign key(owner_id,in_transaction_id) references public.fd_transactions(owner_id,id) on delete cascade);
create table public.fd_mapping_presets(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null,mapping jsonb not null,header_row integer not null default 0,created_at timestamptz not null default now(),unique(owner_id,account_id),foreign key(owner_id,account_id) references public.fd_accounts(owner_id,id) on delete cascade);
create table public.fd_preferences(owner_id uuid primary key references auth.users(id) on delete cascade,balance_alerts boolean not null default true,created_at timestamptz not null default now());
create table public.fd_audit_log(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,action text not null,detail text not null default '',created_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['fd_businesses','fd_accounts','fd_categories','fd_category_rules','fd_gwamok_aliases','fd_uploads','fd_transactions','fd_recurring_items','fd_inter_company_links','fd_mapping_presets','fd_preferences','fd_audit_log'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);execute format('create policy finance_owner on public.%I for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()))',t);if t<>'fd_preferences' then execute format('create index %I on public.%I(owner_id)',t||'_owner_idx',t);end if;end loop;end $$;
create index fd_transactions_owner_date on public.fd_transactions(owner_id,txn_date desc,id);
create index fd_transactions_account_date on public.fd_transactions(owner_id,account_id,txn_date);
create index fd_transactions_category on public.fd_transactions(owner_id,category_id);
create index fd_transactions_upload on public.fd_transactions(owner_id,upload_id);
create index fd_accounts_business on public.fd_accounts(owner_id,business_id);
create index fd_recurring_business on public.fd_recurring_items(owner_id,business_id);
create index fd_rules_category on public.fd_category_rules(owner_id,category_id);
create index fd_uploads_account on public.fd_uploads(owner_id,account_id);
create index fd_links_out on public.fd_inter_company_links(owner_id,out_transaction_id);
create index fd_links_in on public.fd_inter_company_links(owner_id,in_transaction_id);

create function public.fd_check_link() returns trigger language plpgsql security invoker set search_path='' as $$
declare outgoing public.fd_transactions; incoming public.fd_transactions;
begin
 select * into outgoing from public.fd_transactions where id=new.out_transaction_id and owner_id=new.owner_id for update;
 select * into incoming from public.fd_transactions where id=new.in_transaction_id and owner_id=new.owner_id for update;
 if outgoing.id is null or incoming.id is null or outgoing.direction<>'out' or incoming.direction<>'in' or not outgoing.is_internal or not incoming.is_internal or outgoing.amount<>incoming.amount or outgoing.business_id=incoming.business_id then raise exception 'Invalid internal transfer pair';end if;
 return new;
end $$;
create trigger fd_validate_link before insert or update on public.fd_inter_company_links for each row execute function public.fd_check_link();
create function public.fd_unlink_changed_transaction() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.is_internal is distinct from old.is_internal or new.amount is distinct from old.amount or new.direction is distinct from old.direction or new.business_id is distinct from old.business_id then
  delete from public.fd_inter_company_links where owner_id=new.owner_id and (out_transaction_id=new.id or in_transaction_id=new.id);
 end if;
 return new;
end $$;
create trigger fd_unlink_changed_transaction before update on public.fd_transactions for each row execute function public.fd_unlink_changed_transaction();
revoke all on function public.fd_check_link(),public.fd_unlink_changed_transaction() from public,anon;

create view public.fd_v_account_balance with(security_invoker=true) as select a.owner_id,a.id as account_id,a.business_id,case when a.opening_balance_date is null or a.opening_balance_date>(now() at time zone 'Asia/Seoul')::date then null else a.opening_balance+coalesce(sum(case when t.direction='in' then t.amount else -t.amount end),0) end as balance from public.fd_accounts a left join public.fd_transactions t on t.account_id=a.id and t.owner_id=a.owner_id and t.txn_date>=a.opening_balance_date and t.txn_date<=(now() at time zone 'Asia/Seoul')::date group by a.id;
create view public.fd_v_business_monthly with(security_invoker=true) as select owner_id,business_id,date_trunc('month',txn_date)::date as month,sum(case when direction='in' then amount else 0 end) as income,sum(case when direction='out' then amount else 0 end) as expense,sum(case when direction='in' then amount else -amount end) as net from public.fd_transactions group by owner_id,business_id,date_trunc('month',txn_date);
create view public.fd_v_consolidated_monthly with(security_invoker=true) as select owner_id,date_trunc('month',txn_date)::date as month,sum(case when direction='in' then amount else 0 end) as income,sum(case when direction='out' then amount else 0 end) as expense from public.fd_transactions where not is_internal group by owner_id,date_trunc('month',txn_date);
create view public.fd_v_category_summary with(security_invoker=true) as select owner_id,business_id,category_id,direction,sum(amount) as amount from public.fd_transactions group by owner_id,business_id,category_id,direction;
revoke all on public.fd_v_account_balance,public.fd_v_business_monthly,public.fd_v_consolidated_monthly,public.fd_v_category_summary from anon;
grant select on public.fd_v_account_balance,public.fd_v_business_monthly,public.fd_v_consolidated_monthly,public.fd_v_category_summary to authenticated;

create function public.fd_import_transactions(p_account uuid,p_upload uuid,p_rows jsonb) returns integer language plpgsql security invoker set search_path='' as $$ declare business uuid; inserted integer; begin if auth.uid() is null then raise exception 'Unauthorized';end if;select business_id into strict business from public.fd_accounts where id=p_account and owner_id=auth.uid();if not exists(select 1 from public.fd_uploads where id=p_upload and account_id=p_account and owner_id=auth.uid()) then raise exception 'Upload account mismatch';end if;if jsonb_array_length(p_rows)>500 then raise exception 'Batch too large';end if;insert into public.fd_transactions(owner_id,business_id,account_id,upload_id,txn_date,amount,direction,description,raw_gwamok,category_id,is_internal,balance,tax_invoice,dedup_hash) select auth.uid(),business,p_account,p_upload,x.txn_date,x.amount,x.direction,x.description,x.raw_gwamok,x.category_id,x.is_internal,x.balance,x.tax_invoice,x.dedup_hash from jsonb_to_recordset(p_rows) as x(txn_date date,amount bigint,direction text,description text,raw_gwamok text,category_id uuid,is_internal boolean,balance bigint,tax_invoice boolean,dedup_hash text) on conflict(account_id,dedup_hash) do nothing;get diagnostics inserted=row_count;return inserted;end $$;
revoke all on function public.fd_import_transactions(uuid,uuid,jsonb) from public,anon;grant execute on function public.fd_import_transactions(uuid,uuid,jsonb) to authenticated;

create function public.fd_delete_my_data() returns void language plpgsql security invoker set search_path='' as $$ begin if auth.uid() is null then raise exception 'Unauthorized';end if;delete from public.fd_inter_company_links where owner_id=auth.uid();delete from public.fd_transactions where owner_id=auth.uid();delete from public.fd_uploads where owner_id=auth.uid();delete from public.fd_mapping_presets where owner_id=auth.uid();delete from public.fd_recurring_items where owner_id=auth.uid();delete from public.fd_accounts where owner_id=auth.uid();delete from public.fd_businesses where owner_id=auth.uid();delete from public.fd_category_rules where owner_id=auth.uid();delete from public.fd_gwamok_aliases where owner_id=auth.uid();delete from public.fd_categories where owner_id=auth.uid();delete from public.fd_preferences where owner_id=auth.uid();delete from public.fd_audit_log where owner_id=auth.uid();end $$;
revoke all on function public.fd_delete_my_data() from public,anon;grant execute on function public.fd_delete_my_data() to authenticated;

insert into storage.buckets(id,name,public,file_size_limit) values('finance-uploads','finance-uploads',false,10485760) on conflict(id) do nothing;
create policy finance_files_read on storage.objects for select to authenticated using(bucket_id='finance-uploads' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy finance_files_insert on storage.objects for insert to authenticated with check(bucket_id='finance-uploads' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy finance_files_delete on storage.objects for delete to authenticated using(bucket_id='finance-uploads' and (storage.foldername(name))[1]=(select auth.uid())::text);
